class Solution {
public:
    int minLengthAfterRemovals(vector<int>& nums) {
        int n = nums.size();
        int mid = nums[n / 2];
        int left = lower_bound(nums.begin(), nums.end(), mid) - nums.begin();
        int right = upper_bound(nums.begin(), nums.end(), mid) - nums.begin();
        int max_freq = right - left;
        if (max_freq > n / 2) return 2 * max_freq - n;
        return n % 2;
    }
};

class Solution {
    public int minLengthAfterRemovals(List<Integer> nums) {
        int n = nums.size();
        int mid = nums.get(n / 2);
        int left = lowerBound(nums, mid);
        int right = upperBound(nums, mid);
        int maxFreq = right - left;
        if (maxFreq > n / 2) return 2 * maxFreq - n;
        return n % 2;
    }
    private int lowerBound(List<Integer> nums, int target) {
        int lo = 0, hi = nums.size();
        while (lo < hi) {
            int m = (lo + hi) / 2;
            if (nums.get(m) < target) lo = m + 1;
            else hi = m;
        }
        return lo;
    }
    private int upperBound(List<Integer> nums, int target) {
        int lo = 0, hi = nums.size();
        while (lo < hi) {
            int m = (lo + hi) / 2;
            if (nums.get(m) <= target) lo = m + 1;
            else hi = m;
        }
        return lo;
    }
}

