var minLengthAfterRemovals = function(nums) {
    const n = nums.length;
    const mid = nums[n >> 1];
    let lo = 0, hi = n;
    while (lo < hi) {
        const m = (lo + hi) >> 1;
        if (nums[m] < mid) lo = m + 1;
        else hi = m;
    }
    const left = lo;
    lo = 0; hi = n;
    while (lo < hi) {
        const m = (lo + hi) >> 1;
        if (nums[m] <= mid) lo = m + 1;
        else hi = m;
    }
    const right = lo;
    const maxFreq = right - left;
    if (maxFreq > (n >> 1)) return 2 * maxFreq - n;
    return n % 2;
};
